import subprocess, struct, os
EXE="/workspace/executable"
def info(args, data=None):
    if data is None: data=os.urandom(3000000)
    r=subprocess.run([EXE,"-c","-q"]+args, input=data, capture_output=True, cwd="/tmp/t")
    out=r.stdout
    if len(out)<7 or out[:4]!=b'\x04"M\x18':
        return f"rc={r.returncode} len={len(out)} err={r.stderr[:150]}"
    flg,bd=out[4],out[5]
    i=7; blocks=[]
    while i < len(out):
        sz=struct.unpack('<I',out[i:i+4])[0]
        if sz==0: break
        blocks.append(sz & 0x7fffffff); i+=4+(sz&0x7fffffff)
        if flg&0x10: i+=4
    return f"rc={r.returncode} BD_id={(bd>>4)&7} nblocks={len(blocks)} blockcomps={blocks[:5]} err={r.stderr[:80]}"
for bs in ["-B64K","-B64KB","-B65K","-B256K","-B1M","-B1MB","-B4M","-B4KB","-B4MB","-B4096KB","-B100KB","-B7K","-B4G","-B4T","-B4KBx"]:
    print(bs, info([bs]))
for bs in ["-B4","-B40","-B400","-B4000","-B40000"]:
    print(bs, info([bs]))
PY
"}

