    if slave_in: os.close(slave_in)
    err=b""; out=b""
    # If stdin tty, we won't feed; process should refuse immediately? Close master_in? It may wait? Give timeout
    try:
        # For piped stdin send data
        if not stdin_tty:
            p.stdin.write(b"hello\n"); p.stdin.close()
        # wait
        p.wait(timeout=2)
    except Exception as e:
        print("wait err",e); p.kill(); p.wait()
    if stdout_tty:
        # read
        fcntl.fcntl(master_out, fcntl.F_SETFL, os.O_NONBLOCK)
        try:
            while True:
                try:
                    c=os.read(master_out,4096)
