#define XX_P2 2246822519U
#define XX_P3 3266489917U
#define XX_P4 668265263U
#define XX_P5 374761393U
static uint32_t xx_rol(uint32_t x, int r){ return (x<<r)|(x>>(32-r)); }
static uint32_t xx_rd32(const uint8_t*p){ return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24); }
