                b=src[ip++]; litlen+=b;
            }while(b==255);
        }
        if(ip+litlen>src_len){
            if(partial){
                size_t avail=src_len-ip;
                if(op+avail>dst_cap) return -1;
                memcpy(dst+op, src+ip, avail); op+=avail; *partial=1; return (int)op;
            }
            return -1;
