        if(op+litlen>dst_cap) return -1;
        memcpy(dst+op, src+ip, litlen); ip+=litlen; op+=litlen;
        if(ip>=src_len) break; /* last literals */
        if(ip+2>src_len){ if(partial){*partial=1; return (int)op;} return -1; }
