}

/* ---- fast compressor ---- */
#define FAST_HASHLOG 13
#define FAST_HASHSIZE (1<<FAST_HASHLOG)
static uint32_t fast_hash4(const uint8_t* combined, size_t pos){
    uint32_t v=rd32le(combined+pos);
    return (v*2654435761U) >> (32-FAST_HASHLOG);
}
static void emit_len_ext(uint8_t** outp, size_t l){
