    return (size_t)(out-dst);
}

/* ---- HC-ish compressor (greedy + lazy, hash chains) ---- */
#define HC_HASHLOG 15
#define HC_HASHSIZE (1<<HC_HASHLOG)
static uint32_t hc_hash4(const uint8_t* p){
    uint32_t v=rd32le(p);
