}
static size_t hc_match_len(const uint8_t* a, const uint8_t* b, size_t maxlen){
    size_t i=0; while(i<maxlen && a[i]==b[i]) i++; return i;
}
static size_t lz4_compress_block_hc(const uint8_t* src, size_t src_len,
                                    const uint8_t* prefix, size_t prefix_len,
                                    int level, int favor_dec_speed,
