    return (size_t)(out-dst);
}

static size_t compress_block_dispatch(const uint8_t* src, size_t len,
                                      const uint8_t* prefix, size_t prefix_len,
                                      int clevel, int favor_dec_speed,
                                      uint8_t* dst, size_t dst_cap){
    if(clevel<=0){
        int accel;
        if(clevel==0) accel=1;
        else {
            /* --fast=N => clevel=-N ; map acceleration approximately */
            long a = -(long)clevel;
            if(a<1) a=1; if(a>1000000) a=1000000;
            accel=(int)(a*2); /* observed --fast=1 behaves close to accel 2 */
            if(accel<2) accel=2;
        }
        return lz4_compress_block_fast(src,len,prefix,prefix_len,accel,dst,dst_cap);
    }
    if(clevel==1){
        return lz4_compress_block_fast(src,len,prefix,prefix_len,1,dst,dst_cap);
    }
    if(clevel>12) clevel=12;
    return lz4_compress_block_hc(src,len,prefix,prefix_len,clevel,favor_dec_speed,dst,dst_cap);
}
