#define XX_P4 668265263U
#define XX_P5 374761393U
static uint32_t xx_rol(uint32_t x, int r){ return (x<<r)|(x>>(32-r)); }
static uint32_t xx_rd32(const uint8_t*p){ return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24); }
static uint32_t xxhash32(const void* data, size_t len, uint32_t seed){
    const uint8_t* p=(const uint8_t*)data; const uint8_t* end=p+len; uint32_t h;
    if(len>=16){
        uint32_t v1=seed+XX_P1+XX_P2, v2=seed+XX_P2, v3=seed, v4=seed-XX_P1;
        do{
            v1+=xx_rd32(p)*XX_P2; v1=xx_rol(v1,13); v1*=XX_P1; p+=4;
            v2+=xx_rd32(p)*XX_P2; v2=xx_rol(v2,13); v2*=XX_P1; p+=4;
            v3+=xx_rd32(p)*XX_P2; v3=xx_rol(v3,13); v3*=XX_P1; p+=4;
            v4+=xx_rd32(p)*XX_P2; v4=xx_rol(v4,13); v4*=XX_P1; p+=4;
        }while(p<=end-16);
        h=xx_rol(v1,1)+xx_rol(v2,7)+xx_rol(v3,12)+xx_rol(v4,18);
    }else h=seed+XX_P5;
    h+=(uint32_t)len;
    while(p+4<=end){ h+=xx_rd32(p)*XX_P3; h=xx_rol(h,17)*XX_P4; p+=4; }
    while(p<end){ h+=(*p)*XX_P5; h=xx_rol(h,11)*XX_P1; p++; }
    h^=h>>15; h*=XX_P2; h^=h>>13; h*=XX_P3; h^=h>>16; return h;
}
typedef struct { uint32_t v1,v2,v3,v4; uint64_t total; uint8_t buf[16]; size_t buflen; } XxhState;
static void xxh_init(XxhState*s){ s->v1=XX_P1+XX_P2; s->v2=XX_P2; s->v3=0; s->v4=0-XX_P1; s->total=0; s->buflen=0; }
static void xxh_update(XxhState*s, const void*data, size_t len){
    const uint8_t*p=(const uint8_t*)data; s->total+=len;
    if(s->buflen+len<16){ memcpy(s->buf+s->buflen,p,len); s->buflen+=len; return; }
    if(s->buflen){
        size_t fill=16-s->buflen; memcpy(s->buf+s->buflen,p,fill);
        const uint8_t*q=s->buf;
        s->v1+=xx_rd32(q)*XX_P2; s->v1=xx_rol(s->v1,13)*XX_P1; q+=4;
        s->v2+=xx_rd32(q)*XX_P2; s->v2=xx_rol(s->v2,13)*XX_P1; q+=4;
        s->v3+=xx_rd32(q)*XX_P2; s->v3=xx_rol(s->v3,13)*XX_P1; q+=4;
        s->v4+=xx_rd32(q)*XX_P2; s->v4=xx_rol(s->v4,13)*XX_P1;
        p+=fill; len-=fill; s->buflen=0;
    }
    while(len>=16){
        s->v1+=xx_rd32(p)*XX_P2; s->v1=xx_rol(s->v1,13)*XX_P1; p+=4;
        s->v2+=xx_rd32(p)*XX_P2; s->v2=xx_rol(s->v2,13)*XX_P1; p+=4;
        s->v3+=xx_rd32(p)*XX_P2; s->v3=xx_rol(s->v3,13)*XX_P1; p+=4;
        s->v4+=xx_rd32(p)*XX_P2; s->v4=xx_rol(s->v4,13)*XX_P1; p+=4;
        len-=16;
    }
    if(len){ memcpy(s->buf,p,len); s->buflen=len; }
}
static uint32_t xxh_digest(XxhState*s){
    uint32_t h; const uint8_t*p=s->buf; const uint8_t*end=s->buf+s->buflen;
    if(s->total>=16) h=xx_rol(s->v1,1)+xx_rol(s->v2,7)+xx_rol(s->v3,12)+xx_rol(s->v4,18);
    else h=XX_P5;
    h+=(uint32_t)s->total;
    while(p+4<=end){ h+=xx_rd32(p)*XX_P3; h=xx_rol(h,17)*XX_P4; p+=4; }
    while(p<end){ h+=(*p)*XX_P5; h=xx_rol(h,11)*XX_P1; p++; }
    h^=h>>15; h*=XX_P2; h^=h>>13; h*=XX_P3; h^=h>>16; return h;
}

/* ================= globals ================= */
static const char* g_prog = "executable";
static int g_display = 2; /* displayLevel */
static int g_pause = 0;
static void dispf(int level, const char* fmt, ...);
#include <stdarg.h>
static void dispf(int level, const char* fmt, ...){
    va_list ap; if(g_display < level) return;
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
