/* ================= LZ4 block codec ================= */
static uint16_t rd16le(const uint8_t*p){ return (uint16_t)(p[0]|(p[1]<<8)); }
static uint32_t rd32le(const uint8_t*p){ return xx_rd32(p); }
static void wr16le(uint8_t*p, uint16_t v){ p[0]=v&0xff; p[1]=(v>>8)&0xff; }
static void wr32le(uint8_t*p, uint32_t v){ p[0]=v&0xff; p[1]=(v>>8)&0xff; p[2]=(v>>16)&0xff; p[3]=(v>>24)&0xff; }

/* Decompress one block. prefix is history (<=65536). Returns decoded length or -1 on error.
   If partial != NULL, allows truncated compressed input: stores decoded-so-far and sets *partial=1 instead of error when input runs out. */
static int lz4_decompress_block(const uint8_t* src, size_t src_len,
                                const uint8_t* prefix, size_t prefix_len,
                                uint8_t* dst, size_t dst_cap, int* partial){
    size_t ip=0, op=0;
    if(partial) *partial=0;
    if(src_len==0) return 0;
    while(ip<src_len){
        unsigned token=src[ip++];
        size_t litlen=token>>4;
        if(litlen==15){
            unsigned b;
            do{
                if(ip>=src_len){ if(partial){*partial=1; return (int)op;} return -1; }
                b=src[ip++]; litlen+=b;
            }while(b==255);
        }
        if(ip+litlen>src_len){
            if(partial){
                size_t avail=src_len-ip;
                if(op+avail>dst_cap) return -1;
                memcpy(dst+op, src+ip, avail); op+=avail; *partial=1; return (int)op;
            }
            return -1;
        }
        if(op+litlen>dst_cap) return -1;
        memcpy(dst+op, src+ip, litlen); ip+=litlen; op+=litlen;
        if(ip>=src_len) break; /* last literals */
        if(ip+2>src_len){ if(partial){*partial=1; return (int)op;} return -1; }
        {
            size_t offset=rd16le(src+ip); ip+=2;
            size_t matchlen=token&15;
            size_t start_op=op;
            if(matchlen==15){
                unsigned b;
                do{
                    if(ip>=src_len){ if(partial){*partial=1; return (int)op;} return -1; }
                    b=src[ip++]; matchlen+=b;
                }while(b==255);
            }
            matchlen+=4;
            if(offset==0) return -1;
            if(offset>prefix_len+op) return -1;
            if(op+matchlen>dst_cap) return -1;
            /* byte-by-byte copy allowing overlap and prefix */
            {
                size_t k;
                for(k=0;k<matchlen;k++){
                    size_t cur=op+k;
                    size_t spos=prefix_len+cur-offset; /* position in virtual space */
                    uint8_t v;
                    if(spos<prefix_len) v=prefix[spos];
                    else v=dst[spos-prefix_len];
                    (void)start_op;
                    dst[cur]=v;
                }
            }
            op+=matchlen;
        }
    }
    return (int)op;
}

/* ---- fast compressor ---- */
#define FAST_HASHLOG 13
#define FAST_HASHSIZE (1<<FAST_HASHLOG)
static uint32_t fast_hash4(const uint8_t* combined, size_t pos){
    uint32_t v=rd32le(combined+pos);
    return (v*2654435761U) >> (32-FAST_HASHLOG);
}
static void emit_len_ext(uint8_t** outp, size_t l){
    uint8_t* out=*outp;
    while(l>=255){ *out++=255; l-=255; }
    *out++=(uint8_t)l; *outp=out;
}
/* Compress src (with prefix history). dst must be large enough (bound). Returns compressed size, 0 on failure/too big. */
static size_t lz4_compress_block_fast(const uint8_t* src, size_t src_len,
                                      const uint8_t* prefix, size_t prefix_len,
                                      int acceleration,
                                      uint8_t* dst, size_t dst_cap){
    size_t combined_len, plen=prefix_len, i;
    uint8_t* combined; size_t ip, anchor; int32_t* table;
    uint8_t* out=dst; uint8_t* out_end=dst+dst_cap;
    if(src_len==0) return 0;
    if(plen>65536) { prefix+=plen-65536; plen=65536; }
    combined_len=plen+src_len;
    combined=(uint8_t*)malloc(combined_len?combined_len:1);
    if(!combined) return 0;
    if(plen) memcpy(combined, prefix, plen);
    memcpy(combined+plen, src, src_len);
    if(src_len<13){
        /* literal only */
        size_t lit=src_len;
        if(out>=out_end){ free(combined); return 0; }
        if(lit>=15){ *out++=0xF0; { uint8_t* o=out; emit_len_ext(&o, lit-15); out=o; } }
        else *out++=(uint8_t)(lit<<4);
        if((size_t)(out_end-out)<lit){ free(combined); return 0; }
        memcpy(out, src, lit); out+=lit;
        free(combined); return (size_t)(out-dst);
    }
    table=(int32_t*)malloc(sizeof(int32_t)*FAST_HASHSIZE);
    if(!table){ free(combined); return 0; }
    for(i=0;i<FAST_HASHSIZE;i++) table[i]=-1;
    /* insert dictionary/prefix positions (those fully inside prefix) */
    if(plen>=4){
        size_t p;
        for(p=0;p+4<=plen;p++){
            table[fast_hash4(combined,p)]=(int32_t)p;
        }
    }
    {
        size_t match_limit = combined_len-5; /* virtual */
        size_t mf_limit = plen + (src_len-12+1); /* exclusive-ish: ip_rel <= src_len-12 ; virtual ip < mf_limit */
        ip=plen; anchor=plen;
        while(ip < mf_limit){
            /* search */
            size_t forward=ip; size_t step=1;
            unsigned search_nb=(unsigned)(acceleration<<6);
            int found=0; int32_t match=-1; size_t cur=ip;
            if(acceleration<1) acceleration=1;
            search_nb=(unsigned)(acceleration<<6);
            while(1){
                uint32_t hv; int32_t cand;
                cur=forward; forward+=step; step=search_nb>>6; search_nb+=1;
                if(forward>=mf_limit && cur>=mf_limit) break;
                if(cur>=mf_limit) break;
                hv=fast_hash4(combined,cur);
                cand=table[hv]; table[hv]=(int32_t)cur;
                if(cand>=0 && cur-(size_t)cand<=65535 && memcmp(combined+cand, combined+cur,4)==0){
                    ip=cur; match=cand; found=1; break;
                }
            }
            if(!found) break;
            /* backward extension */
            while(ip>anchor && match>0 && combined[ip-1]==combined[match-1]){ ip--; match--; }
            /* sequence(s) */
            while(1){
                size_t lit_len=ip-anchor;
                size_t offset=ip-(size_t)match;
                size_t ip0=ip; size_t match_len;
                uint8_t* token;
                if(out>=out_end){ free(table); free(combined); return 0; }
                token=out++;
                if(lit_len>=15){ *token=(uint8_t)0xF0; { uint8_t*o=out; emit_len_ext(&o, lit_len-15); out=o; } }
                else *token=(uint8_t)(lit_len<<4);
                if((size_t)(out_end-out)<lit_len+2){ free(table); free(combined); return 0; }
                memcpy(out, combined+anchor, lit_len); out+=lit_len;
                wr16le(out, (uint16_t)offset); out+=2;
                ip+=4; match+=4;
                while(ip<match_limit && combined[ip]==combined[match]){ ip++; match++; }
                match_len=ip-ip0;
                {
                    size_t ml=match_len-4;
                    if(ml>=15){ *token|=15; { uint8_t*o=out; emit_len_ext(&o, ml-15); out=o; } }
                    else *token|=(uint8_t)ml;
                }
                anchor=ip;
                if(ip>=mf_limit){
                    /* will exit to last literals */
                    ip=combined_len; /* marker */
                    break;
                }
                /* insert ip-2 */
                if(ip>=2) table[fast_hash4(combined, ip-2)]=(int32_t)(ip-2);
                /* repeat offset check */
                {
                    int64_t cand=(int64_t)ip-(int64_t)offset;
                    if(cand>=0 && memcmp(combined+cand, combined+ip,4)==0){
                        match=(int32_t)cand;
                        continue;
                    }
                }
                break;
            }
            if(ip>=combined_len) break;
        }
        /* last literals */
        {
            size_t lit=combined_len-anchor;
            if(out>=out_end){ free(table); free(combined); return 0; }
            if(lit>=15){ *out++=0xF0; { uint8_t*o=out; emit_len_ext(&o, lit-15); out=o; } }
            else *out++=(uint8_t)(lit<<4);
            if((size_t)(out_end-out)<lit){ free(table); free(combined); return 0; }
            memcpy(out, combined+anchor, lit); out+=lit;
        }
    }
    free(table); free(combined);
    return (size_t)(out-dst);
}

/* ---- HC-ish compressor (greedy + lazy, hash chains) ---- */
#define HC_HASHLOG 15
#define HC_HASHSIZE (1<<HC_HASHLOG)
static uint32_t hc_hash4(const uint8_t* p){
    uint32_t v=rd32le(p);
    return (v*2654435761U) >> (32-HC_HASHLOG);
}
static size_t hc_match_len(const uint8_t* a, const uint8_t* b, size_t maxlen){
    size_t i=0; while(i<maxlen && a[i]==b[i]) i++; return i;
}
static size_t lz4_compress_block_hc(const uint8_t* src, size_t src_len,
                                    const uint8_t* prefix, size_t prefix_len,
                                    int level, int favor_dec_speed,
                                    uint8_t* dst, size_t dst_cap){
    size_t plen=prefix_len, combined_len, i;
    uint8_t* combined; int32_t* head; int32_t* prev;
    uint8_t* out=dst; uint8_t* out_end=dst+dst_cap;
    size_t ip, anchor; int max_search;
    static const int searches[13]={0,8,8,16,32,64,128,256,512,1024,2048,4096,8192};
    if(src_len==0) return 0;
    if(level<1) level=1; if(level>12) level=12;
    max_search=searches[level];
    if(plen>65536){ prefix+=plen-65536; plen=65536; }
    combined_len=plen+src_len;
    combined=(uint8_t*)malloc(combined_len?combined_len:1);
    head=(int32_t*)malloc(sizeof(int32_t)*HC_HASHSIZE);
    prev=(int32_t*)malloc(sizeof(int32_t)*(combined_len?combined_len:1));
    if(!combined||!head||!prev){ free(combined); free(head); free(prev); return 0; }
    if(plen) memcpy(combined,prefix,plen);
    memcpy(combined+plen,src,src_len);
    for(i=0;i<HC_HASHSIZE;i++) head[i]=-1;
    for(i=0;i<combined_len;i++) prev[i]=-1;
    /* insert prefix positions */
    if(plen>=4){
        size_t p;
        for(p=0;p+4<=plen;p++){ uint32_t h=hc_hash4(combined+p); prev[p]=head[h]; head[h]=(int32_t)p; }
    }
    if(src_len<13){
        size_t lit=src_len;
        if(lit>=15){ *out++=0xF0; {uint8_t*o=out; emit_len_ext(&o,lit-15); out=o;} } else *out++=(uint8_t)(lit<<4);
        memcpy(out,src,lit); out+=lit; free(combined); free(head); free(prev); return (size_t)(out-dst);
    }
    {
        size_t match_limit=combined_len-5;
        size_t mf_limit=plen+(src_len-12+1);
        ip=plen; anchor=plen;
        while(ip<mf_limit){
            /* find best match at ip */
            size_t best_len=0; int32_t best_pos=-1; int attempts=0; int32_t cand;
            uint32_t h;
            if(ip+4>combined_len) break;
            h=hc_hash4(combined+ip);
            cand=head[h];
            while(cand>=0 && attempts<max_search){
                size_t off=ip-(size_t)cand;
                if(off==0 || off>65535){ cand=prev[cand]; attempts++; continue; }
                if(combined[cand]==combined[ip]){
                    size_t ml=hc_match_len(combined+cand, combined+ip, match_limit-ip);
                    if(ml>=4){
                        /* backward extension benefit */
                        size_t bip=ip, bcand=(size_t)cand;
                        while(bip>anchor && bcand>0 && combined[bip-1]==combined[bcand-1]){ bip--; bcand--; }
                        {
                            size_t ext=ip-bip; size_t total=ml+ext;
                            if(total>best_len){ best_len=total; best_pos=(int32_t)bcand; /* remember extended start via bip */ }
                        }
                    }
                }
                cand=prev[cand]; attempts++;
            }
            /* insert current position */
            { uint32_t hh=hc_hash4(combined+ip); prev[ip]=head[hh]; head[hh]=(int32_t)ip; }
            if(best_len<4){ ip++; continue; }
            /* compute actual start after backward extension */
            {
                size_t bip=ip; int32_t bcand=best_pos;
                /* recompute backwards from best_pos counterpart: best_pos already extended start, and ip should move back same amt */
                /* We stored best_pos as extended candidate; need extended ip: */
                /* Derive: during evaluation we had bip; recompute deterministically: */
                {
                    /* find counterpart: candidate originally such that... simpler: back-extend from ip/best_match_original not stored.
                       We instead treat best_pos as candidate aligned to ip if no backext was applied in length calc confusion.
                       To avoid misalignment, recompute: assume best_pos corresponds to ip (we extended both, so ip_ext = ip - (total - forward_len)).
                       We don't have forward_len stored; approximate by re-extending: */
                    size_t eip=ip; size_t ec=(size_t)best_pos;
                    /* best_pos was already back-extended, and total length includes extension. Match forward from best_pos vs ip would start not aligned.
                       So instead, walk: while eip>anchor && ec>0 && combined[eip-1]==combined[ec-1] with ec initially being unextended candidate.
                       Since best_pos is extended, this loop will generally not move. Use best_pos and adjust ip by checking alignment:
                       The decoded match should start at position: ip - (something). We can compute start by aligning so that (ip - start_ip) == (candidate_original - best_pos).
                       We lack candidate_original. Fallback: use best_pos as candidate for ip (no shift). Length may be slightly off but still valid if bytes match forward from ip. */
                    (void)eip; (void)ec; (void)bip; (void)bcand;
                }
                /* Ensure forward match from ip with best_pos is valid; if not, find length */
                {
                    size_t fwd=0;
                    if(best_pos>=0 && (size_t)best_pos<ip) fwd=hc_match_len(combined+best_pos, combined+ip, match_limit-ip);
                    if(fwd>=4 && fwd<best_len){
                        /* The extra was backward extension: shift ip back by (best_len-fwd) if possible */
                        size_t ext=best_len-fwd;
                        if(ext<=ip-anchor){
                            /* check bytes before */
                            size_t k; int ok=1;
                            for(k=0;k<ext;k++){ if(combined[ip-ext+k]!=combined[(size_t)best_pos-ext+k]){ /* best_pos-ext may underflow handled by ext<=best_pos check */ if((int64_t)best_pos-(int64_t)ext<0){ ok=0; break; } } }
                            if(ok && (size_t)best_pos>=ext){ ip-=ext; best_pos-=(int32_t)ext; fwd=best_len; }
                            else best_len=fwd;
                        } else best_len=fwd;
                    } else if(fwd>=4) best_len=fwd;
                    else { ip++; continue; }
                }
            }
            /* lazy evaluation: check next position for a clearly better match */
            if(best_len< (size_t)(level>=10? 9: 6) && ip+1<mf_limit){
                /* evaluate ip+1 quickly */
                size_t nbest=0; uint32_t hh=hc_hash4(combined+ip+1); int32_t c2=head[hh]; int att=0;
                while(c2>=0 && att<max_search){
                    if(ip+1-(size_t)c2<=65535 && combined[c2]==combined[ip+1]){
                        size_t ml=hc_match_len(combined+c2, combined+ip+1, match_limit-(ip+1));
                        if(ml>nbest) nbest=ml;
                    }
                    c2=prev[c2]; att++;
                }
                if(nbest>best_len){
                    ip++; continue;
                }
            }
            /* emit sequence */
            {
                size_t lit_len=ip-anchor; size_t offset=ip-(size_t)best_pos; uint8_t* token;
                size_t endpos=ip+best_len; size_t p;
                if(favor_dec_speed && best_len> (size_t) (level>=9? 64: 32)){
                    /* keep as is; favor decSpeed in original mainly affects HC target, ignore */
                }
                if(out>=out_end){ free(combined); free(head); free(prev); return 0; }
                token=out++;
                if(lit_len>=15){ *token=0xF0; {uint8_t*o=out; emit_len_ext(&o,lit_len-15); out=o;} } else *token=(uint8_t)(lit_len<<4);
                if((size_t)(out_end-out)<lit_len+2){ free(combined); free(head); free(prev); return 0; }
                memcpy(out, combined+anchor, lit_len); out+=lit_len;
                wr16le(out,(uint16_t)offset); out+=2;
                {
                    size_t ml=best_len-4;
                    if(ml>=15){ *token|=15; {uint8_t*o=out; emit_len_ext(&o,ml-15); out=o;} } else *token|=(uint8_t)ml;
                }
                /* insert positions inside match (up to end-2) */
                for(p=ip+1;p+1<endpos && p<mf_limit;p++){
                    if(p+4<=combined_len){ uint32_t hh=hc_hash4(combined+p); prev[p]=head[hh]; head[hh]=(int32_t)p; }
                }
                ip=endpos; anchor=ip;
            }
        }
        {
            size_t lit=combined_len-anchor;
            if(lit>=15){ *out++=0xF0; {uint8_t*o=out; emit_len_ext(&o,lit-15); out=o;} } else *out++=(uint8_t)(lit<<4);
            memcpy(out, combined+anchor, lit); out+=lit;
        }
    }
    free(combined); free(head); free(prev);
    return (size_t)(out-dst);
}

static size_t compress_block_dispatch(const uint8_t* src, size_t len,
                                      const uint8_t* prefix, size_t prefix_len,
                                      int clevel, int favor_dec_speed,
                                      uint8_t* dst, size_t dst_cap){
    if(clevel<=0){
        int accel;
        if(clevel==0) accel=1;
        else {
            /* --fast=N => clevel=-N ; map acceleration approximately */
            long a = -(long)clevel;
