static void apply_file_stat(const char* srcname, const char* dstname, FILE* srcfile){
    struct stat st;
    (void)srcname;
    if(!srcfile || srcfile==stdin) return;
    if(is_stdout_name(dstname)||is_null_name(dstname)) return;
    if(fstat(fileno(srcfile), &st)!=0) return;
    if(!S_ISREG(st.st_mode)) {
        /* still apply for e.g. /dev/null? original compressed /dev/null to file and mode? skip */
        /* Actually regular check above: /dev/null is char device; skip */
        /* but if stat of a normal file, it's REG */
    }
    chmod(dstname, st.st_mode & 07777);
    {
        struct timespec times[2];
        /* preserve only mtime in atime?? observed atime not preserved; set atime to dst's current (leave) by using utimens with atime = current time of file */
        struct stat dstst;
        if(stat(dstname,&dstst)==0){
            times[0]=dstst.st_atim;
            times[1]=st.st_mtim;
            utimensat(AT_FDCWD, dstname, times, 0);
        }
    }
}

/* dictionary loading */
static void load_dictionary_or_throw(void){
    FILE* f; long sz; size_t cap, len=0;
    if(!g_dict_name) return;
    if(file_is_directory(g_dict_name)){
        errf("lz4: %s is a directory -- ignored \n", g_dict_name);
        throw_msg(27, "Error 27 : Dictionary error : could not open dictionary file \n");
    }
    if(is_stdin_name(g_dict_name)) f=stdin;
    else {
        f=fopen(g_dict_name,"rb");
        if(!f){ errf("%s: %s \n", g_dict_name, strerror(errno)); throw_msg(27, "Error 27 : Dictionary error : could not open dictionary file \n"); }
    }
    cap=1<<16; g_dict_data=(uint8_t*)malloc(cap); len=0;
    for(;;){
        size_t r;
        if(len==cap){ cap*=2; g_dict_data=(uint8_t*)realloc(g_dict_data,cap); }
        r=fread(g_dict_data+len,1,cap-len,f);
        if(r==0) break;
        len+=r;
    }
    g_dict_len=len;
    if(f!=stdin) fclose(f);
    (void)sz;
}

/* sparse writer */
typedef struct {
    FILE* out; int sparse; unsigned long long logical; int have_nonzero_tail;
} SparseWriter;
static void sparse_write(SparseWriter* w, const uint8_t* data, size_t len){
    if(!w->out) return;
    if(w->out==stdout || !w->sparse){
        if(len) fwrite(data,1,len,w->out);
        w->logical+=len; return;
    }
    /* file sparse */
    {
        size_t i=0;
        while(i<len){
            if(data[i]==0){
                size_t j=i; while(j<len && data[j]==0) j++;
                if(j-i>=512 || (j==len)){
                    /* skip via seek */
                    if(fseek(w->out, (long)(j-i), SEEK_CUR)==0){
                        i=j; w->logical+=(j-i); /* careful: recompute below */
                        /* The above double-count guard: we already advanced, so adjust approach */
                        /* To avoid complexity, we reimplement logical tracking outside */
                    } else {
                        fwrite(data+i,1,j-i,w->out); i=j;
                    }
                    /* logical already incremented incorrectly? We'll maintain logical at start separately */
                    continue;
                } else {
                    fwrite(data+i,1,j-i,w->out); i=j; continue;
                }
            } else {
                size_t j=i; while(j<len && data[j]!=0) j++;
                fwrite(data+i,1,j-i,w->out); i=j;
            }
        }
        w->logical+=0; /* logical tracked by caller via total */
    }
}
