static int default_nbworkers(void){
    long cores = sysconf(_SC_NPROCESSORS_ONLN);
    long w;
    if(cores<1) cores=1;
    /* observed: 64 cores -> 55 */
    w = cores - cores/8 - 1;
    if(w<1) w = cores>1 ? cores-1 : 1;
    if(w<1) w=1;
    if(w>200) w=200;
    return (int)w;
}
