static void print_done(double total_bytes){
    double elapsed, cpu, speed;
    if(g_display<3) return;
    elapsed = now_sec() - g_op_start_time;
    cpu = cpu_sec() - g_op_start_cpu;
    if(elapsed<=0) elapsed=0.000001;
    speed = (total_bytes/1048576.0)/elapsed;
    if(total_bytes==0 && g_total_input_for_done==0){
        /* for successful empty operations original prints 0.00 ; for failures it had garbage. We'll print 0.00 */
        speed = (g_op_start_time==0)?0:speed;
        if(total_bytes==0) speed=0;
    }
    fprintf(stderr, "Done in %.2f s ==> %.2f MiB/s  (cpu load : %u%%)\n",
            elapsed, speed, (unsigned)(elapsed>0 ? (cpu/elapsed*100.0) : 100));
}

