    uint8_t* comp=(uint8_t*)malloc(8388608 + 8388608/255 + 64);
    unsigned long long read_total=0, written_total=0; int first=1;
    (void)input_name;
    fwrite(magic,1,4,dst); written_total+=4;
    for(;;){
        size_t len=fread(buf,1,8388608,src);
