static int g_suppress_done = 0;
static unsigned long long g_multiple_total = 0;

static void compression_summary(unsigned long long read_total, unsigned long long write_total, int legacy){
    int is_stdout;
    /* caller decides display, this prints progress+summary if enabled */
    is_stdout = 0; (void)is_stdout;
    if(legacy){
        fprintf(stderr, "\r                                                                               \rCompressed %llu bytes into %llu bytes ==> %.2f%% \n",
                read_total, write_total, read_total? (double)write_total/(double)read_total*100.0 : 1500.0);
    } else {
        fprintf(stderr, "\r                                                                               \rCompressed %llu bytes into %llu bytes ==> %.2f%%\n",
                read_total, write_total, read_total? (double)write_total/(double)read_total*100.0 : (double)write_total/1.0*100.0);
    }
}
static int show_compress_display(const char* outname){
    if(is_stdout_name(outname)) return g_display>=3;
    return g_display>=2;
}
static int show_decompress_display(const char* outname, int is_test){
    if(!is_test && is_stdout_name(outname)) return g_display>=3;
    return g_display>=2;
}

static size_t block_size_from_id(int id){
    switch(id){ case 4: return 65536; case 5: return 262144; case 6: return 1048576; default: return 4194304; }
}

static int compress_frame_stream(FILE* src, FILE* dst, const char* input_name, const char* output_name,
                                 unsigned long long* out_read, unsigned long long* out_written){
    size_t selected = block_size_from_id(g_block_id);
    uint8_t* chunk = (uint8_t*)malloc(4194304);
    uint8_t* blockbuf = NULL; uint8_t* compbuf=NULL;
    size_t first_len; int eof_known; int eff_id; int eff_indep;
    unsigned long long read_total=0, written_total=0;
    XxhState content_state; int include_content=0; unsigned long long content_size_val=0;
    uint8_t header[32]; size_t header_len=0;
    uint8_t* window=NULL; size_t window_len=0;
    int first_block=1;
    if(!chunk) return 1;
    if(is_stdin_name(input_name) && g_stdin_used_compress){
        free(chunk);
        throw_msg(40, "Error 40 : Error reading first chunk (4194304 bytes) of '%s'  \n", input_name);
    }
    if(is_stdin_name(input_name)) g_stdin_used_compress=1;
    first_len=fread(chunk,1,4194304,src);
    if(first_len<4194304 && ferror(src)){
        free(chunk);
        throw_msg(40, "Error 40 : Error reading first chunk (4194304 bytes) of '%s'  \n", input_name);
    }
    eof_known = first_len<4194304;
    if(eof_known){
        int cand = first_len<=65536?4: first_len<=262144?5: first_len<=1048576?6:7;
        eff_id = cand<g_block_id?cand:g_block_id;
    } else eff_id=g_block_id;
    eff_indep = (eof_known && first_len<=selected) ? 1 : g_block_indep_pref;
    xxh_init(&content_state);
    if(g_content_size){
        struct stat st;
        if(is_stdin_name(input_name)) dispf(2, "warning : --content-size cannot determine size when used with stdin\n");
        if(fstat(fileno(src),&st)==0 && S_ISREG(st.st_mode) && st.st_size>0){ include_content=1; content_size_val=(unsigned long long)st.st_size; }
    }
    {
        uint8_t flg=0x40;
        if(eff_indep) flg|=0x20;
        if(g_block_checksum) flg|=0x10;
        if(include_content) flg|=0x08;
        if(g_frame_crc) flg|=0x04;
        header[header_len++]=0x04; header[header_len++]=0x22; header[header_len++]=0x4d; header[header_len++]=0x18;
        header[header_len++]=(uint8_t)flg;
        header[header_len++]=(uint8_t)(eff_id<<4);
        if(include_content){ int i; for(i=0;i<8;i++) header[header_len++]=(uint8_t)(content_size_val>>(8*i)); }
        header[header_len++]=(uint8_t)((xxhash32(header+4, header_len-4, 0)>>8)&0xff);
    }
    fwrite(header,1,header_len,dst); written_total+=header_len;
    window=(uint8_t*)malloc(65536); window_len=0;
    blockbuf=(uint8_t*)malloc(selected);
    compbuf=(uint8_t*)malloc(selected + selected/255 + 64);
    for(;;){
        size_t chunk_len = first_block ? first_len : fread(chunk,1,4194304,src);
        size_t off=0;
        if(!first_block){
            if(chunk_len==0) break;
            if(chunk_len<4194304 && ferror(src)){ /* treat as end */ }
        }
        read_total += chunk_len;
        while(off<chunk_len){
            size_t blen = selected < (chunk_len-off) ? selected : (chunk_len-off);
            const uint8_t* bsrc=chunk+off;
            size_t csize; uint32_t bhdr;
            const uint8_t* prefix; size_t prefix_len;
            int raw;
            if(eff_indep){ prefix=g_dict_data; prefix_len=g_dict_len; }
            else {
                if(first_block && off==0){ /* window starts as dictionary */
                    if(window_len==0 && g_dict_len){ size_t c=g_dict_len>65536?65536:g_dict_len; memcpy(window, g_dict_data+g_dict_len-c, c); window_len=c; }
                }
                prefix=window; prefix_len=window_len;
            }
            csize=compress_block_dispatch(bsrc, blen, prefix, prefix_len, g_clevel, g_favor_dec, compbuf, selected + selected/255 + 64);
            raw = (csize==0 || csize>=blen);
            bhdr=(uint32_t)(raw?blen:csize); if(raw) bhdr|=0x80000000U;
            {
                uint8_t hb[4]; wr32le(hb,bhdr); fwrite(hb,1,4,dst); written_total+=4;
            }
            if(raw){ fwrite(bsrc,1,blen,dst); written_total+=blen; }
            else { fwrite(compbuf,1,csize,dst); written_total+=csize; }
            if(g_block_checksum){
                uint32_t cs=xxhash32(raw?bsrc:compbuf, raw?blen:csize, 0); uint8_t cb[4]; wr32le(cb,cs); fwrite(cb,1,4,dst); written_total+=4;
            }
            xxh_update(&content_state, bsrc, blen);
            if(!eff_indep){
                /* append to rolling window */
                if(blen>=65536){ memcpy(window, bsrc+blen-65536, 65536); window_len=65536; }
                else {
                    if(window_len+blen>65536){ size_t drop=window_len+blen-65536; memmove(window, window+drop, window_len-drop); window_len-=drop; }
                    memcpy(window+window_len, bsrc, blen); window_len+=blen;
                }
            }
            off+=blen;
        }
        if(first_block){
            first_block=0;
            if(eof_known) break;
            /* loop to read next chunk; if the first chunk was exactly full, continue */
            if(first_len<4194304) break;
        }
    }
    {
        uint8_t endm[4]={0,0,0,0}; fwrite(endm,1,4,dst); written_total+=4;
        if(g_frame_crc){ uint32_t cs=xxh_digest(&content_state); uint8_t cb[4]; wr32le(cb,cs); fwrite(cb,1,4,dst); written_total+=4; }
    }
    free(chunk); free(blockbuf); free(compbuf); free(window);
    *out_read=read_total; *out_written=written_total;
    return 0;
}

static int compress_legacy_stream(FILE* src, FILE* dst, const char* input_name,
                                  unsigned long long* out_read, unsigned long long* out_written){
    uint8_t magic[4]={0x02,0x21,0x4c,0x18};
    uint8_t* buf=(uint8_t*)malloc(8388608);
    uint8_t* comp=(uint8_t*)malloc(8388608 + 8388608/255 + 64);
    unsigned long long read_total=0, written_total=0; int first=1;
    (void)input_name;
    fwrite(magic,1,4,dst); written_total+=4;
    for(;;){
        size_t len=fread(buf,1,8388608,src);
        size_t csize; uint8_t hb[4];
        if(len==0) break;
        read_total+=len;
        csize=compress_block_dispatch(buf,len, first?g_dict_data:NULL, first?g_dict_len:0, g_clevel, g_favor_dec, comp, 8388608 + 8388608/255 + 64);
        if(csize==0){ csize=len; memcpy(comp,buf,len); }
        wr32le(hb,(uint32_t)csize); fwrite(hb,1,4,dst); fwrite(comp,1,csize,dst); written_total+=4+csize;
        first=0;
    }
    free(buf); free(comp);
    *out_read=read_total; *out_written=written_total;
    return 0;
}

/* core compress operation; output_name must be resolved. Returns 0/1, throws on fatal errors. */
static int do_compress(const char* input_name, const char* output_name){
    FILE* src; FILE* dst; int notow=0;
    unsigned long long read_total=0, written_total=0;
    double start=now_sec(); double cstart=cpu_sec();
    if(!g_suppress_threads) print_threads_line();
    if(g_legacy && g_display>=3) fprintf(stderr, "! Generating LZ4 Legacy format (deprecated) ! \n");
    load_dictionary_or_throw();
    src=open_input_file(input_name);
    if(!src){ if(!g_suppress_done) { g_op_start_time=start; g_op_start_cpu=cstart; g_total_input_for_done=0; print_done(0); } return 1; }
    dst=open_output_file(output_name, &notow);
    if(!dst){ if(src!=stdin) fclose(src); if(!g_suppress_done){ g_op_start_time=start; g_op_start_cpu=cstart; print_done(0); } return 1; }
    if(g_legacy){
        if(show_compress_display(output_name)) fprintf(stderr, "\rRead : 0 MiB   ==> inf%%   ");
        compress_legacy_stream(src,dst,input_name,&read_total,&written_total);
    } else {
        compress_frame_stream(src,dst,input_name,output_name,&read_total,&written_total);
    }
    if(dst!=stdout) fclose(dst); else fflush(dst);
    if(src!=stdin) {
        apply_file_stat(input_name, output_name, src);
    }
    if(src!=stdin) fclose(src);
    g_multiple_total += read_total;
    if(!g_keep){
        if(remove(input_name)!=0){
            throw_msg(50, "Error 50 : Remove error : %s: %s \n", input_name, strerror(errno));
        }
    }
    if(show_compress_display(output_name)){
        if(!g_legacy) fprintf(stderr, "\rRead : %llu MiB   ==> %.2f%%   ", read_total>>20, read_total? (double)written_total/(double)read_total*100.0 : (double)written_total*100.0);
        compression_summary(read_total, written_total, g_legacy);
    }
    if(!g_suppress_done){ g_op_start_time=start; g_op_start_cpu=cstart; print_done((double)read_total); }
    else { (void)start; (void)cstart; }
    return 0;
}

/* ================= decompression ================= */
#define DEC_BATCH_SIZE 4194304
typedef struct {
    FILE* src; FILE* dst; const char* input_name; const char* output_name;
    int is_test; int pass_through;
    OutWriter writer;
    unsigned long long total_decoded;
    unsigned long long input_pos;
    uint8_t* batch; size_t batch_len; int progress_shown; int progress_enabled;
    uint8_t* window; size_t window_len;
} DecCtx;
static int dec_read(DecCtx* ctx, uint8_t* buf, size_t want){
    size_t r=fread(buf,1,want,ctx->src); ctx->input_pos+=r; return (int)r;
}
static void dec_batch_flush(DecCtx* ctx){
    if(ctx->batch_len==0) return;
    ow_write(&ctx->writer, ctx->batch, ctx->batch_len);
    if(ctx->progress_enabled && !ctx->progress_shown){
        fprintf(stderr, "\rDecompressed : %llu MiB  ", ctx->total_decoded>>20);
        ctx->progress_shown=1;
    }
    ctx->batch_len=0;
}
static void dec_append(DecCtx* ctx, const uint8_t* data, size_t len){
    while(len){
        size_t space, take;
        if(ctx->batch_len==DEC_BATCH_SIZE) dec_batch_flush(ctx);
        space=DEC_BATCH_SIZE-ctx->batch_len; take=space<len?space:len;
        memcpy(ctx->batch+ctx->batch_len, data, take); ctx->batch_len+=take; data+=take; len-=take;
        if(ctx->batch_len==DEC_BATCH_SIZE) dec_batch_flush(ctx);
    }
}
static void dec_window_set_dict(DecCtx* ctx){
    size_t c=g_dict_len>65536?65536:g_dict_len;
    ctx->window_len=0;
    if(c){ memcpy(ctx->window, g_dict_data+g_dict_len-c, c); ctx->window_len=c; }
}
static void dec_window_append(DecCtx* ctx, const uint8_t* data, size_t len){
    if(len>=65536){ memcpy(ctx->window, data+len-65536,65536); ctx->window_len=65536; return; }
    if(ctx->window_len+len>65536){ size_t drop=ctx->window_len+len-65536; memmove(ctx->window, ctx->window+drop, ctx->window_len-drop); ctx->window_len-=drop; }
    memcpy(ctx->window+ctx->window_len, data, len); ctx->window_len+=len;
}
static int read_exact_or_throw26(DecCtx* ctx, uint8_t* buf, size_t n, int flush_before){
    size_t got=0;
    while(got<n){ size_t r=fread(buf+got,1,n-got,ctx->src); if(r==0) break; ctx->input_pos+=r; got+=r; }
    if(got<n){ if(flush_before) dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
    return (int)got;
}

/* LZ4F stream -- first frame magic already consumed */
static int decode_lz4f(DecCtx* ctx, int first_magic_consumed){
    int first_frame=1;
    static const size_t block_sizes[8]={0,0,0,0,65536,262144,1048576,4194304};
    for(;;){
        uint8_t magicb[4]; uint32_t magic;
        if(!first_frame || !first_magic_consumed){
            int got=dec_read(ctx, magicb, 4);
            if(got==0) return 0;
            if(got<4){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
        } else {
            magicb[0]=0x04; magicb[1]=0x22; magicb[2]=0x4d; magicb[3]=0x18;
        }
        first_frame=0; first_magic_consumed=0;
        magic=rd32le(magicb);
        if(magic>=0x184d2a50U && magic<=0x184d2a5fU){
            uint8_t szb[4]; uint32_t sz; uint32_t remaining;
            int got=dec_read(ctx, szb,4);
            if(got<4){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
            sz=rd32le(szb); remaining=sz;
            while(remaining){
                uint8_t skipbuf[8192]; size_t want=remaining>8192?8192:remaining; int r=dec_read(ctx, skipbuf, want);
                if(r<=0){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
                remaining-=(uint32_t)r;
            }
            continue;
        }
        if(magic!=0x184d2204U){
            /* need 7 bytes total to declare unknown */
            uint8_t extra[3]; int got=dec_read(ctx, extra,3);
            if(got<3){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
            throw_msg(34, "Error 34 : Decompression error : ERROR_frameType_unknown \n");
        }
        /* frame header */
        {
            uint8_t hdr[15]; size_t hdr_len=0; uint8_t flg,bd; size_t need_extra; uint8_t hc;
            int got;
            got=dec_read(ctx, hdr,2);
            if(got<2){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
            flg=hdr[0]; bd=hdr[1]; hdr_len=2;
            need_extra=0;
            if(flg&0x08) need_extra+=8;
            if(flg&0x01) need_extra+=4;
            if(need_extra){
                got=dec_read(ctx, hdr+hdr_len, need_extra);
                if(got<(int)need_extra){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
                hdr_len+=need_extra;
            }
            {
                uint8_t hcb[1]; got=dec_read(ctx,hcb,1);
                if(got<1){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
                hc=hcb[0];
            }
            /* validations */
            if( (flg>>6)!=1) throw_msg(34, "Error 34 : Decompression error : ERROR_headerVersion_wrong \n");
            if( (flg&0x02) || (bd&0x80)) throw_msg(34, "Error 34 : Decompression error : ERROR_reservedFlag_set \n");
            {
                int bmid=(bd>>4)&7;
                unsigned long long content_size=0; int has_content=(flg&0x08)!=0;
                int block_indep=(flg&0x20)!=0; int block_cs=(flg&0x10)!=0; int content_cs=(flg&0x04)!=0;
                size_t block_max; XxhState frame_hash; unsigned long long frame_decoded=0;
                size_t hdr_offset=2;
                if(bmid<4||bmid>7) throw_msg(34, "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n");
                if(bd&0x0f) throw_msg(34, "Error 34 : Decompression error : ERROR_reservedFlag_set \n");
                if( ((xxhash32(hdr, hdr_len,0)>>8)&0xff) != hc) throw_msg(34, "Error 34 : Decompression error : ERROR_headerChecksum_invalid \n");
                if(has_content){ int i; for(i=0;i<8;i++) content_size |= (unsigned long long)hdr[hdr_offset++]<<(8*i); }
                block_max=block_sizes[bmid];
                xxh_init(&frame_hash);
                dec_window_set_dict(ctx);
                for(;;){
                    uint8_t szb[4]; uint32_t raw_size; int got2;
                    got2=dec_read(ctx, szb,4);
                    if(got2<4){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
                    raw_size=rd32le(szb);
                    if(raw_size==0){
                        if(has_content && frame_decoded!=content_size) throw_msg(34, "Error 34 : Decompression error : ERROR_frameSize_wrong \n");
                        if(content_cs){
                            uint8_t csb[4]; uint32_t stored;
                            got2=dec_read(ctx, csb,4);
                            if(got2<4){ dec_batch_flush(ctx); throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n"); }
                            stored=rd32le(csb);
                            if(stored!=xxh_digest(&frame_hash)) throw_msg(34, "Error 34 : Decompression error : ERROR_contentChecksum_invalid \n");
                        }
                        dec_batch_flush(ctx);
                        break;
                    }
                    {
                        uint32_t stored_size=raw_size&0x7fffffffU; int is_raw=(raw_size>>31)!=0;
                        uint8_t* stored; uint8_t* decoded; int decoded_len;
                        if(stored_size>block_max) throw_msg(34, "Error 34 : Decompression error : ERROR_maxBlockSize_invalid \n");
                        stored=(uint8_t*)malloc(stored_size?stored_size:1);
                        {
                            size_t gotb=0;
                            while(gotb<stored_size){ size_t r=fread(stored+gotb,1,stored_size-gotb,ctx->src); if(r==0) break; ctx->input_pos+=r; gotb+=r; }
                            if(gotb<stored_size){
                                if(is_raw){
                                    ctx->total_decoded+=gotb; frame_decoded+=gotb; xxh_update(&frame_hash, stored, gotb);
                                    dec_append(ctx, stored, gotb); dec_batch_flush(ctx);
                                } else {
                                    dec_batch_flush(ctx);
                                }
                                free(stored);
                                throw_msg(26, "Error 26 : LZ4F frame decoding could not complete: invalid frame \n");
                            }
                        }
                        if(block_cs){
                            uint8_t csb[4]; uint32_t stored_cs; int gotc=dec_read(ctx, csb,4);
                            if(gotc<4){ free(stored); throw_msg(34, "Error 34 : Decompression error : ERROR_blockChecksum_invalid \n"); }
                            stored_cs=rd32le(csb);
                            if(stored_cs!=xxhash32(stored, stored_size,0)){ free(stored); throw_msg(34, "Error 34 : Decompression error : ERROR_blockChecksum_invalid \n"); }
                        }
                        decoded=(uint8_t*)malloc(block_max?block_max:1);
                        if(is_raw){ memcpy(decoded, stored, stored_size); decoded_len=(int)stored_size; }
                        else {
                            decoded_len=lz4_decompress_block(stored, stored_size, ctx->window, ctx->window_len, decoded, block_max, NULL);
                            if(decoded_len<0){ free(stored); free(decoded); throw_msg(34, "Error 34 : Decompression error : ERROR_decompressionFailed \n"); }
                        }
                        free(stored);
                        xxh_update(&frame_hash, decoded, (size_t)decoded_len);
                        frame_decoded+=(unsigned long long)decoded_len; ctx->total_decoded+=(unsigned long long)decoded_len;
                        dec_append(ctx, decoded, (size_t)decoded_len);
                        if(block_indep) dec_window_set_dict(ctx); else dec_window_append(ctx, decoded, (size_t)decoded_len);
                        free(decoded);
                    }
                }
            }
        }
    }
}

#define LEGACY_MAX_DECODED 8388608
#define LEGACY_MAX_COMPRESSED (8388608 + 8388608/255 + 16)
static int decode_legacy(DecCtx* ctx, uint32_t* transition_magic){
    uint8_t* pending=NULL; size_t pending_len=0;
    dec_window_set_dict(ctx);
    for(;;){
        uint8_t szb[4]; int got=dec_read(ctx, szb,4); uint32_t sz;
        if(got==0){
            if(pending){ dec_append(ctx, pending, pending_len); free(pending); }
            return 0;
        }
        if(got<4){ free(pending); throw_msg(61, "Error 61 : Error: cannot read block size in Legacy format \n"); }
        sz=rd32le(szb);
        if(sz> (uint32_t)LEGACY_MAX_COMPRESSED){
            if(pending){ dec_append(ctx, pending, pending_len); free(pending); }
            *transition_magic=sz; return 2;
        }
        if(sz==0){ free(pending); throw_msg(64, "Error 64 : Decoding Failed ! Corrupted input detected ! \n"); }
        {
            uint8_t* stored=(uint8_t*)malloc(sz); uint8_t* decoded=(uint8_t*)malloc(LEGACY_MAX_DECODED);
            size_t gotb=0; int dlen;
            while(gotb<sz){ size_t r=fread(stored+gotb,1,sz-gotb,ctx->src); if(r==0) break; ctx->input_pos+=r; gotb+=r; }
            if(gotb<sz){ free(stored); free(decoded); free(pending); throw_msg(63, "Error 63 : Read error : cannot access compressed block ! \n"); }
            dlen=lz4_decompress_block(stored, sz, ctx->window, ctx->window_len, decoded, LEGACY_MAX_DECODED, NULL);
            free(stored);
            if(dlen<0){ free(decoded); free(pending); throw_msg(64, "Error 64 : Decoding Failed ! Corrupted input detected ! \n"); }
            if(pending){ dec_append(ctx, pending, pending_len); free(pending); pending=NULL; }
            pending=(uint8_t*)malloc(dlen?dlen:1); if(dlen) memcpy(pending, decoded, (size_t)dlen); pending_len=(size_t)dlen;
            ctx->total_decoded+=(unsigned long long)dlen;
            dec_window_append(ctx, decoded, (size_t)dlen);
            free(decoded);
        }
    }
}

/* returns 0 ok, 1 stream-followed-by-undecodable */
static int decode_stream(DecCtx* ctx){
    int after_data=0;
    uint32_t pending_magic=0; int have_pending=0;
    for(;;){
        uint8_t magicb[4]; uint32_t magic; int got;
        if(have_pending){ magic=pending_magic; have_pending=0; magicb[0]=magic&0xff; magicb[1]=(magic>>8)&0xff; magicb[2]=(magic>>16)&0xff; magicb[3]=(magic>>24)&0xff; got=4; }
        else {
            got=dec_read(ctx, magicb,4);
            if(got==0) return 0;
            if(got<4) throw_msg(40, "Error 40 : Unrecognized header : Magic Number unreadable \n");
            magic=rd32le(magicb);
        }
        if(magic==0x184d2204U){
            return decode_lz4f(ctx, 1);
        } else if(magic==0x184c2102U){
            uint32_t trans=0; int st=decode_legacy(ctx, &trans);
            if(st==0) return 0;
            pending_magic=trans; have_pending=1; after_data=1; continue;
        } else if(magic>=0x184d2a50U && magic<=0x184d2a5fU){
            uint8_t szb[4]; uint32_t sz; int g2=dec_read(ctx, szb,4); uint32_t rem;
            if(g2<4) throw_msg(42, "Error 42 : Stream error : skippable size unreadable \n");
            sz=rd32le(szb); rem=sz;
            while(rem){
                uint8_t buf[8192]; size_t want=rem>8192?8192:rem; int r=dec_read(ctx, buf, want);
                if(r<=0) throw_msg(43, "Error 43 : Stream error : cannot skip skippable area \n");
                rem-=(uint32_t)r;
            }
            after_data=1; continue;
        } else {
            if(!after_data && ctx->pass_through){
                ow_write(&ctx->writer, magicb,4); ctx->total_decoded+=4;
                for(;;){ uint8_t buf[65536]; int r=dec_read(ctx, buf, sizeof(buf)); if(r<=0) break; ow_write(&ctx->writer, buf, (size_t)r); ctx->total_decoded+=(unsigned long long)r; }
                return 0;
            }
            if(!after_data) throw_msg(44, "Error 44 : Unrecognized header : file cannot be decoded \n");
            return 1;
        }
    }
}

static void decompress_summary(DecCtx* ctx, const char* input_name){
    if(!ctx->progress_shown){
        fprintf(stderr, "\rDecompressed : %llu MiB  ", ctx->total_decoded>>20);
    }
    fprintf(stderr, "\r                                                                               \r%-32s : decoded %llu bytes \n",
            input_name, ctx->total_decoded);
}

/* core decompress; test mode discards output internally */
static int do_decompress(const char* input_name, const char* output_name, int is_test){
    FILE* src; FILE* dst; int notow=0; DecCtx ctx; int status; double start=now_sec(); double cstart=cpu_sec();
    const char* effective_out = is_test ? NULL_NAME : output_name;
    load_dictionary_or_throw();
    dst=open_output_file(effective_out, &notow);
    if(!dst){ if(!g_suppress_done){ g_op_start_time=start; g_op_start_cpu=cstart; print_done(0); } return 1; }
    src=open_input_file(input_name);
    if(!src){ if(dst!=stdout) fclose(dst); if(!g_suppress_done){ g_op_start_time=start; g_op_start_cpu=cstart; print_done(0); } return 1; }
    memset(&ctx,0,sizeof(ctx)); ctx.src=src; ctx.dst=dst; ctx.input_name=input_name; ctx.output_name=effective_out; ctx.is_test=is_test;
    ctx.pass_through = (!is_test && g_cflag && g_overwrite && is_stdout_name(effective_out));
    ctx.progress_enabled = show_decompress_display(effective_out, is_test);
    ctx.batch=(uint8_t*)malloc(DEC_BATCH_SIZE); ctx.window=(uint8_t*)malloc(65536);
    ctx.writer.out=dst;
    ctx.writer.sparse=0;
    if(!is_stdout_name(effective_out) && !is_null_name(effective_out)){
        ctx.writer.sparse = (g_sparse_mode!=-1);
    } else if(is_stdout_name(effective_out)){
        ctx.writer.sparse = (g_sparse_mode==1);
    }
    if(is_null_name(effective_out)) ctx.writer.sparse=0;
    /* ensure test mode empty decode still prints progress at summary time */
    status=decode_stream(&ctx);
    dec_batch_flush(&ctx);
    ow_finish(&ctx.writer);
    free(ctx.batch); free(ctx.window);
    if(status==1){
        if(g_display>=3){
            if(ctx.progress_shown) fprintf(stderr, "Stream followed by undecodable data%s \n", is_stdin_name(input_name)?"":" at position ");
            else fprintf(stderr, "Stream followed by undecodable data%s", is_stdin_name(input_name)?" \n":"");
            if(!is_stdin_name(input_name)) {
                /* we printed prefix above in two different forms; to keep exact formatting handled below */
            }
            /* The above two-step print is messy; actual messages are composed in caller variants below (rewritten by summary logic) */
            /* To avoid duplicate messy output, this branch is re-handled: */
            (void)0;
        }
        /* NOTE: stream-followed verbose message is printed in do_decompress_ex below */
        if(dst!=stdout) fclose(dst);
        if(src!=stdin) fclose(src);
        if(!g_suppress_done){ g_op_start_time=start; g_op_start_cpu=cstart; print_done(0); }
        return 1;
    }
    if(dst!=stdout) fclose(dst); else fflush(dst);
    if(src!=stdin) apply_file_stat(input_name, effective_out, src);
    if(src!=stdin) fclose(src);
    g_multiple_total += ctx.total_decoded;
    if(!g_keep){
        if(remove(input_name)!=0){
            /* progress should be visible before error if enabled */
            if(ctx.progress_enabled && !ctx.progress_shown) fprintf(stderr, "\rDecompressed : %llu MiB  ", ctx.total_decoded>>20);
            throw_msg(45, "Error 45 : Remove error : %s: %s \n", input_name, strerror(errno));
        }
    }
    if(show_decompress_display(effective_out, is_test)){
        /* rebuild a minimal ctx for summary printing */
        DecCtx sctx; memset(&sctx,0,sizeof(sctx)); sctx.total_decoded=ctx.total_decoded; sctx.progress_shown=ctx.progress_shown;
        decompress_summary(&sctx, input_name);
    }
    return 0;
}
