/* ================= string list ================= */
typedef struct { char** items; size_t count; size_t cap; } StrList;
static void sl_add(StrList* l, const char* s){
    if(l->count==l->cap){ l->cap=l->cap?l->cap*2:16; l->items=(char**)realloc(l->items, sizeof(char*)*l->cap); }
    l->items[l->count++]=strdup(s);
}
static void sl_free(StrList* l){ size_t i; for(i=0;i<l->count;i++) free(l->items[i]); free(l->items); l->items=NULL; l->count=l->cap=0; }

static StrList g_files = {0};
static const char* g_input_name = "stdin";
static const char* g_output_name = NULL;
static int g_input_assigned = 0;

static void activate_collect(void){
    if(!g_collect_active){ g_collect_active=1; g_input_name=STDIN_NAME; g_input_assigned=0; }
    g_multiple=1;
}
static void add_positional(const char* token, int literal){
    if(g_collect_active){
        if(!literal && strcmp(token,"-")==0) return;
        sl_add(&g_files, token);
    } else {
        if(!g_input_assigned){
            g_input_name = (!literal && strcmp(token,"-")==0) ? STDIN_NAME : token;
            g_input_assigned=1;
        } else if(g_output_name==NULL){
            g_output_name = (!literal && strcmp(token,"-")==0) ? STDOUT_NAME : token;
        } else {
            sl_add(&g_files, token);
        }
    }
}

static void collect_dir(const char* path, StrList* out){
    DIR* d=opendir(path); struct dirent* e;
    if(!d){ sl_add(out, path); return; }
    while((e=readdir(d))!=NULL){
        char* child; size_t need;
        if(strcmp(e->d_name,".")==0||strcmp(e->d_name,"..")==0) continue;
        need=strlen(path)+strlen(e->d_name)+2; child=(char*)malloc(need);
        if(path[0] && path[strlen(path)-1]=='/') snprintf(child,need,"%s%s",path,e->d_name); else snprintf(child,need,"%s/%s",path,e->d_name);
        if(file_is_directory(child)) collect_dir(child, out); else sl_add(out, child);
        free(child);
    }
    closedir(d);
}
static void expand_recursive(StrList* out){
    size_t i; StrList res={0};
    for(i=0;i<g_files.count;i++){
        const char* name=g_files.items[i];
        if(g_recursive && file_is_directory(name)){
            size_t before=res.count;
            collect_dir(name,&res);
            if(res.count==before) sl_add(&res,name);
        } else sl_add(&res,name);
    }
    sl_free(&g_files); g_files=res; (void)out;
}

