static char* dup_strip_lz4(const char* name){ size_t l=strlen(name); char* s=strdup(name); if(l>=4) s[l-4]='\0'; return s; }
static char* dup_add_lz4(const char* name){ char* s=(char*)malloc(strlen(name)+5); strcpy(s,name); strcat(s,".lz4"); return s; }

static int process_multiple_files(void){
    int orig_display=g_display; int mode; size_t i; int errors=0;
    double start=now_sec(); double cstart=cpu_sec();
    expand_recursive(NULL);
    if(g_files.count==0) return 0;
    if(g_op==OP_TEST) mode=OP_TEST;
    else if(g_op==OP_DECOMPRESS) mode=OP_DECOMPRESS;
    else if(g_op==OP_COMPRESS) mode=OP_COMPRESS;
    else mode = ends_with_lz4(g_files.items[0]) ? OP_DECOMPRESS : OP_COMPRESS;
    if(orig_display>=3 && mode==OP_COMPRESS) print_threads_line();
    if(orig_display>=4 && mode==OP_DECOMPRESS){
        fprintf(stderr, "Using stdout for output \n");
        fprintf(stderr, "Sparse File Support automatically disabled on stdout ; to force-enable it, add --sparse command \n");
    }
    g_suppress_threads=1; g_suppress_done=1; g_in_multiple=1;
    if(orig_display>0) g_display=orig_display-1; else g_display=orig_display;
    g_multiple_total=0;
    for(i=0;i<g_files.count;i++){
        const char* file=g_files.items[i]; int result=0; char* derived=NULL;
        if(mode==OP_DECOMPRESS || mode==OP_TEST){
            if(!(ends_with_lz4(file) && strlen(file)>4)){
                errf("File extension doesn't match expected LZ4_EXTENSION (.lz4); will not process file: %s\n", file);
                errors++; continue;
            }
        }
        if(mode==OP_TEST){
            result=do_decompress(file, STDOUT_NAME, 0);
        } else if(mode==OP_DECOMPRESS){
            const char* outname;
            if(g_output_name && is_stdout_name(g_output_name)) outname=STDOUT_NAME;
            else { derived=dup_strip_lz4(file); outname=derived; }
            result=do_decompress(file,outname,0);
        } else {
            const char* outname;
            if(g_output_name && is_stdout_name(g_output_name)) outname=STDOUT_NAME;
            else { derived=dup_add_lz4(file); outname=derived; }
            result=do_compress(file,outname);
        }
        if(result) errors+=result;
        free(derived);
    }
    g_display=orig_display; g_in_multiple=0; g_suppress_threads=0; g_suppress_done=0;
    if(orig_display>=3){ g_op_start_time=start; g_op_start_cpu=cstart; print_done((double)g_multiple_total); }
    return errors;
}

