    g_multiple_total=0;
    if(mode==OP_TEST) result=do_decompress(g_input_name, STDOUT_NAME, 0);
    else if(mode==OP_DECOMPRESS) result=do_decompress(g_input_name,outname,0);
    else result=do_compress(g_input_name,outname);
    g_display=orig_display; g_in_multiple=0; g_suppress_threads=0; g_suppress_done=0;
    if(orig_display>=3){ g_op_start_time=start; g_op_start_cpu=cstart; print_done((double)g_multiple_total); }
    return result;
}

/* ================= single processing ================= */
static int process_single(void){
    int mode; int is_test=0; const char* input=g_input_name; const char* output=g_output_name; char* derived=NULL; int result;
    if(g_op==OP_TEST){ mode=OP_DECOMPRESS; is_test=1; }
    else if(g_op==OP_DECOMPRESS) mode=OP_DECOMPRESS;
    else if(g_op==OP_COMPRESS) mode=OP_COMPRESS;
