    }
    if(mode==OP_DECOMPRESS && !is_test && !output && !is_stdin_name(input)){
        if(!ends_with_lz4(input) || strlen(input)<=4){
            return cannot_determine_output();
        }
        derived=dup_strip_lz4(input);
        if(g_display>=2) fprintf(stderr, "Decoding file %s \n", derived);
        output=derived;
    }
    if(!output){
        if(is_stdin_name(input)) output=STDOUT_NAME;
        else if(mode==OP_COMPRESS){
            derived=dup_add_lz4(input);
            if(g_display>=2) fprintf(stderr, "Compressed filename will be : %s \n", derived);
            output=derived;
        } else {
            output=NULL_NAME;
        }
    } else if(mode==OP_COMPRESS && !g_output_name){
        /* not possible */
    }
    /* console protection */
    if(is_stdin_name(input) && isatty(STDIN_FILENO)){
