typedef struct { int type; /*0 lz4,1 legacy,2 skip*/ int block_id; int indep; int has_cs; unsigned long long compressed; unsigned long long uncompressed; int has_uncomp; } FrameInfo;
static void format_human_size(char* buf, size_t bufsz, unsigned long long sz){
    if(sz<1024) snprintf(buf,bufsz,"%.2f",(double)sz);
    else if(sz<1024ULL*1024ULL) snprintf(buf,bufsz,"%.2fK",(double)sz/1024.0);
    else if(sz<1024ULL*1024ULL*1024ULL) snprintf(buf,bufsz,"%.2fM",(double)sz/1048576.0);
    else snprintf(buf,bufsz,"%.2fG",(double)sz/1073741824.0);
}
static const char* frame_type_name(int t){ return t==0?"LZ4Frame":t==1?"LegacyFrame":"SkippableFrame"; }
static int list_one_file(const char* fname, int index, int total, int* out_error_code){
    struct stat st; FILE* f; uint8_t* data=NULL; size_t fsize=0, cap=0; FrameInfo frames[1024]; int nframes=0; size_t off=0; int parse_error=0; int thrown_code=0; size_t error_pos=0;
    *out_error_code=0;
    if(stat(fname,&st)!=0 || !S_ISREG(st.st_mode)){
        errf("lz4: %s is not a regular file \n", fname); return 1;
    }
    if(g_display>=3){
        printf("%s(%d/%d)\n", fname, index+1, total);
        printf("     Frame           Type Block Checksum           Compressed         Uncompressed     Ratio\n");
        fflush(stdout);
    }
    f=fopen(fname,"rb"); if(!f){ errf("lz4: %s is not a regular file \n", fname); return 1; }
