    while(off<fsize && !parse_error && !thrown_code){
        uint32_t magic;
        if(fsize-off<4){ thrown_code=40; break; }
        magic=rd32le(data+off);
        if(magic==0x184d2204U){
            size_t start=off; size_t pos; uint8_t flg,bd; size_t hdr_extra; unsigned long long csize=0; unsigned long long unc=0; int has_unc=0;
            if(fsize-off<7){ thrown_code=71; break; }
            flg=data[off+4]; bd=data[off+5];
            /* validate like frame */
            if((flg>>6)!=1){ parse_error=1; error_pos=off+4; break; }
