                switch(c){
                    case 'V': print_version(); return 0;
                    case 'h': do_help(0); break;
                    case 'H': do_help(1); break;
                    case 'z': g_op=OP_COMPRESS; g_bench_dec=0; p++; break;
                    case 'd': if(g_op==OP_BENCH) g_bench_dec=1; else g_op=OP_DECOMPRESS; p++; break;
                    case 't': g_op=OP_TEST; g_bench_dec=0; p++; break;
                    case 'f': g_overwrite=1; p++; break;
                    case 'k': g_keep=1; p++; break;
                    case 'c': g_cflag=1; g_stdout_forced=1; g_output_name=STDOUT_NAME; p++; break;
                    case 'm': activate_collect(); p++; break;
                    case 'r': g_recursive=1; activate_collect(); p++; break;
                    case 'l': g_legacy=1; p++; break;
                    case 'q': g_display--; p++; break;
                    case 'v': g_display++; p++; break;
                    case 'p': g_pause=1; p++; break;
                    case 'S': p++; break;
                    case 'B': {
                        p++;
                        if(isdigit((unsigned char)*p)){
                            const char* start_num=p; uint32_t val=parse_u32_advance(&p); (void)start_num;
                            if( ((val>=4&&val<=7)||val>=32) ){
                                size_t raw;
                                if(val>=4&&val<=7){ g_block_id=(int)val; raw=block_size_from_id((int)val); }
                                else { raw=val; g_block_id= val<=65536?4: val<=262144?5: val<=1048576?6:7; }
                                g_block_raw=(unsigned)raw; g_block_set=1;
                                if(g_display>=2){
                                    if(raw<1024) fprintf(stderr, "using blocks of size %zu bytes \n", raw);
                                    else fprintf(stderr, "using blocks of size %zu KB \n", raw>>10);
                                }
                            } else return bad_parameters();
                        }
                        while(*p=='D'||*p=='I'||*p=='X'){
                            if(*p=='D') g_block_indep_pref=0;
                            else if(*p=='I') g_block_indep_pref=1;
                            else if(*p=='X') g_block_checksum=1;
                            p++;
                        }
                        break;
                    }
                    case 'D': {
                        p++;
                        if(*p){ g_dict_name=p; p+=strlen(p); }
                        else {
                            if(i+1>=argc) return bad_parameters();
                            g_dict_name=argv[++i];
                        }
                        break;
                    }
                    case 'T': {
                        p++;
                        if(isdigit((unsigned char)*p)){ g_nbworkers=parse_u32_advance(&p); }
                        break;
                    }
                    case 'b': {
                        if(g_op==OP_DECOMPRESS) g_bench_dec=1; else if(g_op!=OP_BENCH) g_bench_dec=0;
                        g_op=OP_BENCH; activate_collect(); p++;
                        if(isdigit((unsigned char)*p)){ g_bench_low=(int)parse_u32_advance(&p); if(!g_bench_high_set) g_bench_high=g_bench_low; }
                        break;
                    }
                    case 'e': p++; if(isdigit((unsigned char)*p)){ g_bench_high=(int)parse_u32_advance(&p); g_bench_high_set=1; } break;
                    case 'i': p++; if(isdigit((unsigned char)*p)){ g_bench_time=parse_u32_advance(&p); } break;
                    default: return bad_parameters();
                }
            }
            continue;
        }
        add_positional(arg,0);
    }
    /* dispatch */
    if(g_op==OP_BENCH){
        if(g_display>=3) fprintf(stderr, "- test >= %u seconds per compression / decompression -\n", g_bench_time);
        print_banner();
        result=do_bench();
        if(g_pause){ fprintf(stderr, "Press enter to continue...\n"); (void)getchar(); }
        return result;
    }
    if(g_op==OP_LIST){
        print_banner();
        result=do_list();
        if(g_pause){ fprintf(stderr, "Press enter to continue...\n"); (void)getchar(); }
        return result;
    }
    if(!g_multiple && g_files.count>0){
        errf("Error : %s won't be used ! Do you want multiple input files (-m) ? \n", g_files.items[0]);
        return 1;
    }
    print_banner();
    if(g_multiple){
        if(g_files.count>0) result=process_multiple_files();
        else result=process_multiple_fallback();
    } else {
        result=process_single();
    }
    if(g_pause){ fprintf(stderr, "Press enter to continue...\n"); (void)getchar(); }
    return result;
}
