        if(strcmp(nobext,"lz4cat")==0){ g_op=OP_DECOMPRESS; g_cflag=1; g_stdout_forced=1; g_output_name=STDOUT_NAME; g_overwrite=1; activate_collect(); }
        else if(strcmp(nobext,"unlz4")==0){ g_op=OP_DECOMPRESS; }
    }
