/* ================= argument parsing helpers ================= */
static uint32_t parse_u32_advance(const char** pp){
    const char* p=*pp; uint32_t v=0;
    while(isdigit((unsigned char)*p)){ v=v*10+(uint32_t)(*p-'0'); p++; }
    if(*p=='K'||*p=='k'){ v<<=10; p++; if(*p=='B'||*p=='b') p++; }
    else if(*p=='M'||*p=='m'){ v<<=20; p++; if(*p=='B'||*p=='b') p++; }
    *pp=p; return v;
}
static int parse_threads_checked(const char* s, unsigned* out){
    const char* p=s; uint32_t v=0;
    if(!*s){ *out=0; return 1; }
    if(!isdigit((unsigned char)*p)) return 0;
    while(isdigit((unsigned char)*p)){ v=v*10+(uint32_t)(*p-'0'); p++; }
    if(*p){
        if(*p=='K'||*p=='k'){ v<<=10; p++; }
        else if(*p=='M'||*p=='m'){ v<<=20; p++; }
        else return 0;
        if(*p=='i'){ p++; if(*p=='B'||*p=='b') p++; }
        else if(*p=='B'||*p=='b') p++;
    }
    if(*p) return 0;
    *out=v; return 1;
}
static void threads_error_exit(const char* msg){
    if(g_display>=1) fprintf(stderr, "%s", msg);
    exit(1);
}

/* ================= main ================= */
int main(int argc, char** argv){
    int i; int after_dashdash=0; int result=0;
    const char* arg0 = (argc>0&&argv[0])?argv[0]:"executable";
    const char* base=strrchr(arg0,'/');
    g_prog=base?base+1:arg0;
    if(!g_prog||!*g_prog) g_prog="executable";
    {
        char nobext[512]; size_t l=strlen(g_prog);
        snprintf(nobext,sizeof(nobext),"%s",g_prog);
        if(l>4){ char* suf=nobext+l-4; if(strcasecmp(suf,".exe")==0) *suf='\0'; }
        if(strcmp(nobext,"lz4cat")==0){ g_op=OP_DECOMPRESS; g_cflag=1; g_stdout_forced=1; g_output_name=STDOUT_NAME; g_overwrite=1; activate_collect(); }
        else if(strcmp(nobext,"unlz4")==0){ g_op=OP_DECOMPRESS; }
    }
    /* environment defaults */
    {
        char* e=getenv("LZ4_CLEVEL");
        if(e){
            if(!isdigit((unsigned char)e[0])) fprintf(stderr, "Ignore environment variable setting LZ4_CLEVEL=%s: not a valid unsigned value \n", e);
            else { const char* p=e; uint32_t v=parse_u32_advance(&p); g_clevel=(int)v; }
        }
        e=getenv("LZ4_NBWORKERS");
        if(e){
            if(!isdigit((unsigned char)e[0])) fprintf(stderr, "Ignore environment variable setting LZ4_NBWORKERS=%s: not a valid unsigned value \n", e);
            else { const char* p=e; uint32_t v=parse_u32_advance(&p); g_nbworkers=v; }
        }
    }
    for(i=1;i<argc;i++){
        const char* arg=argv[i];
        if(after_dashdash){ add_positional(arg,1); continue; }
        if(strcmp(arg,"--")==0){ after_dashdash=1; continue; }
        if(arg[0]=='-' && arg[1]=='-'){
            const char* name=arg+2;
            if(strcmp(name,"compress")==0){ g_op=OP_COMPRESS; g_bench_dec=0; }
            else if(strcmp(name,"decompress")==0){ if(g_op==OP_BENCH) g_bench_dec=1; else g_op=OP_DECOMPRESS; }
            else if(strcmp(name,"test")==0){ g_op=OP_TEST; g_bench_dec=0; }
            else if(strcmp(name,"stdout")==0||strcmp(name,"to-stdout")==0){ g_output_name=STDOUT_NAME; g_stdout_forced=1; }
            else if(strcmp(name,"force")==0){ g_overwrite=1; }
            else if(strcmp(name,"no-force")==0){ g_overwrite=0; }
            else if(strcmp(name,"quiet")==0){ g_display--; }
            else if(strcmp(name,"verbose")==0){ g_display++; }
            else if(strcmp(name,"version")==0){ print_version(); return 0; }
            else if(strcmp(name,"help")==0){ do_help(0); }
            else if(strcmp(name,"multiple")==0){ activate_collect(); }
            else if(strcmp(name,"rm")==0){ g_keep=0; }
            else if(strcmp(name,"keep")==0){ g_keep=1; }
            else if(strcmp(name,"frame-crc")==0){ g_frame_crc=1; }
            else if(strcmp(name,"no-frame-crc")==0||strcmp(name,"no-crc")==0){ g_frame_crc=0; }
            else if(strcmp(name,"content-size")==0){ g_content_size=1; }
            else if(strcmp(name,"no-content-size")==0){ g_content_size=0; }
            else if(strcmp(name,"sparse")==0){ g_sparse_mode=1; }
            else if(strcmp(name,"no-sparse")==0){ g_sparse_mode=-1; }
            else if(strcmp(name,"favor-decSpeed")==0){ g_favor_dec=1; }
            else if(strcmp(name,"fast")==0){ g_clevel=-1; }
            else if(strncmp(name,"fast=",5)==0){
                const char* v=name+5; const char* p=v; uint32_t val;
                if(!isdigit((unsigned char)*v)) return bad_parameters();
